text:
{
  "logline": "閉山した銅山の町・尾根野で、郵便配達員の佐伯スミは宛名のない三通の手紙を届けることを望むが、公式記録と町の記憶が食い違っていることに阻まれる。",
  "premise": "閉山から十五年、郵便局に残っていた宛名のない手紙は三通で、差出人は同じ男だった。男は十五年前に死んでいる。",
  "theme": "記録対記憶",
  "elements": {
    "who": "郵便配達員の佐伯スミ",
    "where": "閉山した銅山の町・尾根野",
    "wants": "宛名のない三通の手紙を届けること",
    "obstacle": "公式記録と町の記憶が食い違っていること"
  },
  "similar": [
    {"title": "死者の書", "axis": "world", "difference": "死者は語り手として現れず、手紙という紙だけが残る"},
    {"title": "砂の女", "axis": "structure", "difference": "閉ざされた土地ではなく、閉じた記録の内側に人を閉じ込める"},
    {"title": "黒い雨", "axis": "character", "difference": "記録を書く人ではなく、配達する人が証言を拾い集める"}
  ],
  "prohibitions": [
    {"rule": "手紙の文面を長く引用しない", "check_ja": "各章で引用符の中に手紙の本文が三行以上続かないことを目視で確かめる"},
    {"rule": "死者を現在の行為者として書かない", "check_ja": "死者の名を含む文に、記録・遺品・回想の語があるかを章ごとに確かめる"},
    {"rule": "記録が訂正されたと断定しない", "check_ja": "最終章に訂正・修正・書き直しの断定がないことを確かめる"}
  ],
  "failure_questions": [
    "三通の手紙の差出人が同じ人物だと、第二章までに読者が気づけるか？",
    "記録の食い違いが、本文に書かれた事実と矛盾しないか？"
  ],
  "genre": "novel",
  "audience": "静かな短編を読む大人"
}
